/** 展平为考点列表：{id, subject, path:[...], name, kw} */
function leaves() {
  const out = [];
  const visit = (node, trail, subject) => {
    if (node.kw) { out.push({ id: [...trail, node.name].join("/"), subject, path: trail.slice(1), name: node.name, kw: node.kw }); return; }
    for (const c of node.children || []) visit(c, [...trail, node.name], subject);
  };
  for (const s of SYLLABUS) visit(s, [], s.subject);
  return out;
}

module.exports = { SYLLABUS, leaves };
